// Oct 17: Ranger visuals (Canvas). Neon cores with coloured falloff, ellipse ground rings (y .65), ground light
// pools, flask arcs with shadows, soft smoke puffs and status reticles. Polish later (user: playable first).
import {shotScale,shotLift,shotDX} from './ranger-vfx.js?v=fx-260';
import {RANGER_COLORS,ARROW_COLORS,flaskPos} from './ranger.js?v=fx-260';
import {rangerSoftUpper,rangerSoftGround} from './ranger-soft.js?v=fx-260';
const TAU=Math.PI*2,ease=t=>1-(1-t)*(1-t);
/* Power Shot is fully charged once t reaches the release threshold (charge time, x.6 with Quick Draw); returns {since} or null. */
const chargeFull=r=>{const c=r?.charge;if(!c?.spec?.charge)return null;const need=c.need??c.spec.charge;return c.t>=need?{since:c.t-need}:null;};
const POOL={toxictrail:['#7dff5a','#2f8f2a'],toxic:['#7dff5a','#2f8f2a'],fire:['#ff8a3d','#a8321a'],frost:['#9ff4ff','#3a8fb8'],sludge:['#c9b25a','#4a3e14']};
const POTION={fire:'#ff8a3d',frost:'#9ff4ff',poison:'#9dff5a'};
const flaskColor=f=>f.kind==='grandflask'?'#b35cff':f.kind==='volatile'?'#7dff5a':f.kind==='potion'?(POTION[f.el]??'#b35cff'):f.kind==='bomb'?'#3a3440':'#b35cff';
function ring(ctx,x,y,R,color,width=3,alpha=1,squash=.65){ctx.globalAlpha=alpha;ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.ellipse(x,y,Math.max(1,R),Math.max(1,R*squash),0,0,TAU);ctx.stroke();}
function glow(ctx,x,y,R,color,alpha=.5,squash=1){if(R<=1)return;ctx.save();ctx.globalAlpha=alpha;ctx.translate(x,y);ctx.scale(1,squash);const g=ctx.createRadialGradient(0,0,0,0,0,R);g.addColorStop(0,color);g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,R,0,TAU);ctx.fill();ctx.restore();}
function streak(ctx,x,y,angle,len,color,width){const bx=x-Math.cos(angle)*len,by=y-Math.sin(angle)*len;ctx.lineCap='round';
 ctx.globalAlpha=.28;ctx.strokeStyle=color;ctx.lineWidth=width*3;ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(x,y);ctx.stroke();
 ctx.globalAlpha=.85;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(x,y);ctx.stroke();
 ctx.globalAlpha=1;ctx.strokeStyle='#fff';ctx.lineWidth=Math.max(1,width*.4);ctx.beginPath();ctx.moveTo(x-Math.cos(angle)*len*.45,y-Math.sin(angle)*len*.45);ctx.lineTo(x,y);ctx.stroke();}
function star(ctx,x,y,R,spin,color){ctx.save();ctx.translate(x,y);ctx.rotate(spin);ctx.globalAlpha=.35;ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,R*1.6,0,TAU);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=color;ctx.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4,d=i%2?R*.35:R;ctx.lineTo(Math.cos(a)*d,Math.sin(a)*d);}ctx.closePath();ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(0,0,R*.22,0,TAU);ctx.fill();ctx.restore();}
/* Oct 18 (user): the Falconer hawk is a 3D model. game.js installs the drawer (hero-3d.js drawHawk3D) so this module stays
   importable without three.js (Node tests); the Canvas hawk remains the fallback while it loads. */
let hawk3D=null;export function setHawkDrawer(fn){hawk3D=fn;}
export function drawRangerGround(ctx,r,time,player,targets,shader=false){if(!r)return;ctx.save();rangerSoftGround(ctx,r);
 for(const q of r.pools){const [c1,c2]=POOL[q.kind]??POOL.toxic,fade=Math.min(1,q.remaining/.6,(q.max-q.remaining)/.25+.2);
  /* Oct 19 (user): toxic pools read as round bubbling pools with green rings: soft bed, glowing rim, inner ring, bubbles that rise and pop */
  if(q.kind==='toxictrail'||q.kind==='toxic'){const rise=Math.min(1,(q.max-q.remaining)/.2),R=q.R*(.6+.4*rise);glow(ctx,q.x,q.y,R*1.15,'#1e5a10',.55*fade,.65);glow(ctx,q.x,q.y,R*.85,'#4fd02a',.38*fade,.65);ctx.globalCompositeOperation='lighter';ring(ctx,q.x,q.y,R,'#7dff5a',7,.18*fade);ring(ctx,q.x,q.y,R,'#c8ff8a',2,.75*fade);ring(ctx,q.x,q.y,R*.62,'#a4ff5a',1.5,.35*fade);ctx.globalCompositeOperation='source-over';
   for(let i=0;i<7;i++){const sd=(q.seed??q.x)+i*37,a=sd*1.7,ph=(time*(.7+(i%3)*.25)+i*.29)%1,d=R*(.15+.7*((sd*.13)%1)),bx=q.x+Math.cos(a)*d,by=q.y+Math.sin(a)*d*.65;
    if(ph<.8){const s=1.5+ph*5;ctx.globalAlpha=.85*fade;ctx.fillStyle='#7dff5a';ctx.beginPath();ctx.arc(bx,by-ph*3,s,0,TAU);ctx.fill();ctx.globalAlpha=.9*fade;ctx.fillStyle='#e4ffc8';ctx.beginPath();ctx.arc(bx-s*.35,by-ph*3-s*.35,s*.3,0,TAU);ctx.fill();}
    else{const k=(ph-.8)/.2;ring(ctx,bx,by-2,5+k*7,'#c8ff8a',1.4,(1-k)*.8*fade);}}continue;}glow(ctx,q.x,q.y,q.R*1.1,c2,.55*fade,.65);glow(ctx,q.x,q.y,q.R*.8,c1,.32*fade,.65);ring(ctx,q.x,q.y,q.R,c1,2,.45*fade);
  for(let i=0;i<5;i++){const a=i*1.7+q.x*.01,ph=(time*.9+i*.37)%1,d=q.R*(.25+.55*((i*.31)%1));ctx.globalAlpha=(1-ph)*.7*fade;ctx.fillStyle=c1;ctx.beginPath();ctx.arc(q.x+Math.cos(a)*d,q.y+Math.sin(a)*d*.65-ph*10,2+ph*4,0,TAU);ctx.fill();}}
 if(!shader)for(const v of r.volleys){const p=(time*2)%1;ring(ctx,v.x,v.y,v.R,ARROW_COLORS[v.el]??'#e9f6ff',2,.55);ring(ctx,v.x,v.y,v.R*(.35+.6*p),ARROW_COLORS[v.el]??'#e9f6ff',1.5,.35*(1-p));glow(ctx,v.x,v.y,v.R,'#b8ff8a',.12,.65);}
 if(r.charge&&player){const a=r.charge.angle,f=Math.min(1,r.charge.t/r.charge.spec.charge),len=r.charge.spec.range*(.35+.65*f);ctx.globalAlpha=.25+.45*f;ctx.strokeStyle=ARROW_COLORS.plain;ctx.setLineDash([10,10]);ctx.lineWidth=2+3*f;ctx.beginPath();ctx.moveTo(player.x,player.y);ctx.lineTo(player.x+Math.cos(a)*len,player.y+Math.sin(a)*len);ctx.stroke();ctx.setLineDash([]);
   /* Oct 18: full charge = solid gold aim line + pulsing light pool under the Ranger (ground half of the full-charge glow). */
   const full=chargeFull(r);if(full){const pulse=.5+.5*Math.sin(time*9);ctx.globalAlpha=.35+.25*pulse;ctx.strokeStyle='#ffd36b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(player.x,player.y);ctx.lineTo(player.x+Math.cos(a)*len,player.y+Math.sin(a)*len);ctx.stroke();ctx.globalCompositeOperation='screen';glow(ctx,player.x,player.y,62+8*pulse,'#ffbf4a',.45,.65);ctx.globalCompositeOperation='source-over';}}
 // Hawk catch marker (Draven-style): outer ring = catch area, inner ring closes as the hawk arrives.
 if(r.catchSpot){const q=r.catchSpot,f=Math.min(1,q.t/q.dur),pulse=.6+.4*Math.sin(time*14);glow(ctx,q.x,q.y,q.R*1.3,'#ffcf7a',.25,.65);ring(ctx,q.x,q.y,q.R,'#ffcf7a',2.5,.55+.35*pulse);ring(ctx,q.x,q.y,q.R*(1.9-.9*f),'#fff6d8',2,.4+.5*f);
  if(player&&Math.hypot(player.x-q.x,(player.y-q.y)/.65)<q.R)ring(ctx,q.x,q.y,q.R*.55,'#ffffff',3,.8);}
 for(const h of [r.hawk,...(r.hawkFollow??[])])if(h){ctx.globalAlpha=.28;ctx.fillStyle='#000';ctx.beginPath();ctx.ellipse(h.x,h.y+34,12,5,0,0,TAU);ctx.fill();}
 if(!shader)for(const b of r.shots)glow(ctx,b.x,b.y+24,b.kind==='power'?40:18,b.color,.22,.55);
 for(const f of r.flasks){const t=Math.min(1,f.t/f.dur),x=f.x0+(f.x-f.x0)*t,y=f.y0+20+(f.y-f.y0-20)*t;ctx.globalAlpha=.3;ctx.fillStyle='#000';ctx.beginPath();ctx.ellipse(x,y,7,4,0,0,TAU);ctx.fill();ring(ctx,f.x,f.y,f.spec.radius*(f.kind==='volatile'?1:.8),flaskColor(f),1.5,.35);}
 /* Oct 18 new weapons: placed barrels sit on a faint ring (blast radius) that pulses red once lit; Crossbow reload arc under the archer. */
 for(const b of r.barrels??[]){const lit=b.fuse!=null;ring(ctx,b.x,b.y,b.R,lit?'#ff5a3a':'#c9b25a',lit?2.5:1.2,lit?.8:.22);if(!shader)glow(ctx,b.x,b.y,40,'#c9b25a',.25,.6);}
 if(player&&r.reload){const k=Math.min(1,r.reload.t/r.reload.dur);ctx.globalAlpha=.85;ctx.strokeStyle='#e6ffc8';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(player.x,player.y,34,22,0,-Math.PI/2,-Math.PI/2+TAU*k);ctx.stroke();}
 if(!shader&&r.coneFx&&r.coneFx.look!=='flame'&&r.coneFx.until>(r.shakeT??0)){const f=r.coneFx,c=f.look==='flame'?'#ff8a3d':'#9dff5a';ctx.save();ctx.globalAlpha=.35;ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(f.x,f.y-24);ctx.arc(f.x,f.y-24,f.range,f.angle-f.half,f.angle+f.half);ctx.closePath();ctx.fill();ctx.restore();}
 if(player&&r.buffs.focus>0)ring(ctx,player.x,player.y,44+Math.sin(time*8)*3,RANGER_COLORS.archer,2.5,.7);
 if(player&&r.buffs.enhanced>0){glow(ctx,player.x,player.y,70,RANGER_COLORS.alchemist,.3,.6);ring(ctx,player.x,player.y,52,RANGER_COLORS.alchemist,2,.6);}
 ctx.restore();}
export function drawRangerUpper(ctx,r,time,player,targets,drawBody,shader=false){if(!r)return;ctx.save();
 // Oct 18: Power Shot full-charge glow at the bow hand: onset flash ring + sparks, then a pulsing gold glow with a hot core and orbiting motes until release.
 const full=chargeFull(r);if(full&&player){const a=r.charge.angle,since=full.since,pulse=.5+.5*Math.sin(time*9),tx=player.x+Math.cos(a)*20,ty=player.y-30+Math.sin(a)*12;
  glow(ctx,tx,ty,30+6*pulse,'#ffb43c',.55);ctx.globalCompositeOperation='lighter';glow(ctx,tx,ty,9+3*pulse,'#fff6d8',.9);ctx.globalCompositeOperation='source-over';
  for(let i=0;i<5;i++){const o=time*3+i*TAU/5,z=Math.sin(time*5+i*1.3)*4;ctx.globalAlpha=.6+.4*Math.sin(time*7+i);ctx.fillStyle=i%2?'#fff1c2':'#ffc75a';ctx.beginPath();ctx.arc(tx+Math.cos(o)*16,ty+Math.sin(o)*10+z,1.6+(i%3)*.5,0,TAU);ctx.fill();}
  if(since<.3){const k=since/.3,e=ease(k);ring(ctx,tx,ty+6,10+46*e,'#ffd36b',3*(1-k)+1,1-k,.5);ctx.strokeStyle='#fff3c8';ctx.lineWidth=2;for(let i=0;i<8;i++){const o=i*TAU/8+.4,d0=8+20*e,d1=d0+10*(1-k);ctx.globalAlpha=1-k;ctx.beginPath();ctx.moveTo(tx+Math.cos(o)*d0,ty+Math.sin(o)*d0*.65);ctx.lineTo(tx+Math.cos(o)*d1,ty+Math.sin(o)*d1*.65);ctx.stroke();}}
  ctx.globalAlpha=1;}
 // Smoke: drifting soft puffs.
 for(const sm of r.smokes){const fade=Math.min(1,sm.remaining/.8,(sm.max-sm.remaining)/.2);for(let i=0;i<9;i++){const a=i*TAU/9+time*.3,d=sm.R*(.3+.45*((i*.37)%1)),x=sm.x+Math.cos(a)*d,y=sm.y+Math.sin(a)*d*.6-26-Math.sin(time*1.3+i)*6;glow(ctx,x,y,sm.R*.55,i%3?'#2a3460':'#3a4a8a',.32*fade);}}
 // Shadow clones: translucent purple copies of the archer.
 for(const cl of r.clones){ctx.globalAlpha=.55;glow(ctx,cl.x,cl.y-30,46,RANGER_COLORS.ninja,.4);if(drawBody)drawBody(cl.x,cl.y,cl.row,cl.t<1?Math.floor(time*20)%15:(cl.act>0?Math.floor((1-cl.act/.3)*14):0),cl.t<1?'Rolling':'Attack2',.5);}
 if(shader)for(const b of r.shots){const c=b.ghost?RANGER_COLORS.ninja:b.color,S=shotScale(b)*(b.ghost?.75:1);ctx.globalAlpha=b.ghost?.6:1;
  if(b.kind==='shuriken'||b.look==='star'){ctx.save();ctx.translate(b.x+shotDX(b),b.y-shotLift(b));ctx.rotate(b.spin);ctx.scale(S,S);ctx.fillStyle='#f4f8ff';ctx.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4,d=i%2?2.6:7.5;ctx.lineTo(Math.cos(a)*d,Math.sin(a)*d);}ctx.closePath();ctx.fill();ctx.restore();}
  else if(b.chakram){ctx.save();ctx.translate(b.x+shotDX(b),b.y-shotLift(b));ctx.rotate(b.spin*.7);ctx.scale(S,S);ctx.strokeStyle='#f4f8ff';ctx.lineWidth=2.2;ctx.beginPath();ctx.arc(0,0,11,0,TAU);ctx.stroke();ctx.fillStyle='#f4f8ff';for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);ctx.beginPath();ctx.moveTo(9,-2.5);ctx.lineTo(17,0);ctx.lineTo(9,2.5);ctx.closePath();ctx.fill();}ctx.restore();}
  else if(b.look==='kunai'||b.look==='dagger'){ctx.save();ctx.translate(b.x+shotDX(b),b.y-shotLift(b));ctx.rotate(b.angle);ctx.scale(S,S);ctx.fillStyle='#e8eef8';ctx.beginPath();ctx.moveTo(8,0);ctx.lineTo(-3,-3);ctx.lineTo(-3,3);ctx.closePath();ctx.fill();ctx.fillStyle='#3a3046';ctx.fillRect(-10,-1.2,7,2.4);ctx.restore();}
  else if(b.kind==='arrow'&&b.look!=='bullet'&&b.look!=='pellet'){ctx.save();ctx.translate(shotDX(b),-shotLift(b));/* Oct 18 fix: arrows sat at the sim point, below their glow */const L=(b.look==='bolt'?22:b.look==='longArrow'?30:22)*S,ca=Math.cos(b.angle),sa=Math.sin(b.angle);ctx.strokeStyle='#f2f6ee';ctx.lineWidth=(b.look==='bolt'?2.6:1.6)*S;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(b.x-ca*L,b.y-sa*L);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(b.x-ca*L,b.y-sa*L);ctx.lineTo(b.x-ca*(L+7)-sa*4,b.y-sa*(L+7)+ca*4);ctx.lineTo(b.x-ca*(L+4),b.y-sa*(L+4));ctx.lineTo(b.x-ca*(L+7)+sa*4,b.y-sa*(L+7)-ca*4);ctx.fill();ctx.restore();}}
 else for(const b of r.shots){const c=b.ghost?RANGER_COLORS.ninja:b.color,S=shotScale(b)*(b.ghost?.75:1);ctx.save();ctx.translate(b.x+shotDX(b),b.y-shotLift(b));ctx.scale(S,S);ctx.translate(-b.x,-b.y);drawShotCanvas(ctx,b,c);ctx.restore();}
 function drawShotCanvas(ctx,b,c){if(b.kind==='shuriken')star(ctx,b.x,b.y,9,b.spin,c);else if(b.kind==='bullet')streak(ctx,b.x,b.y,b.angle,20,c,2.5);else if(b.kind==='power')streak(ctx,b.x,b.y,b.angle,70*(b.size??1),c,4.5*(b.size??1));else if(b.look==='pellet'){streak(ctx,b.x,b.y,b.angle,10,'#ffb35a',2.2);}else if(b.look==='chakram'){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.spin*.7);glow(ctx,0,0,26,b.returned?'#ffe6a0':'#3f8bff',.6);ctx.globalAlpha=1;ctx.strokeStyle='#e8f6ff';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,0,12,12,0,0,TAU);ctx.stroke();ctx.fillStyle=c;for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);ctx.beginPath();ctx.moveTo(10,-3);ctx.lineTo(19,0);ctx.lineTo(10,3);ctx.closePath();ctx.fill();}ctx.restore();}else if(b.look==='star')star(ctx,b.x,b.y,8,b.spin,b.ghost?c:'#e8f0ff');else if(b.look==='bullet')streak(ctx,b.x,b.y,b.angle,18,b.ghost?c:'#ffd27a',2.4);else if(b.look==='bolt')streak(ctx,b.x,b.y,b.angle,34,c,4);else if(b.look==='kunai'){streak(ctx,b.x,b.y,b.angle,22,c,2.2);ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.angle);ctx.globalAlpha=1;ctx.fillStyle='#dfe8f5';ctx.beginPath();ctx.moveTo(6,0);ctx.lineTo(-4,-3.5);ctx.lineTo(-4,3.5);ctx.closePath();ctx.fill();ctx.restore();}else streak(ctx,b.x,b.y,b.angle,b.look==='longArrow'?40:28,c,b.ghost?2:b.look==='longArrow'?3.2:2.6);}
 for(const f of r.flasks){const P=flaskPos(f),t=P.t,x=P.x,y=P.y,c=flaskColor(f),S=f.kind==='grandflask'?3.2:f.kind==='bomb'?2.2:f.kind==='potion'?1.7:1.35;glow(ctx,x,y,30*S/1.35,c,shader?.35:.65);ctx.save();ctx.translate(x,y);ctx.rotate(t*(f.kind==='grandflask'?5:9));ctx.scale(S,S);ctx.globalAlpha=1;
  if(f.kind==='bomb'){ctx.fillStyle='#2a2630';ctx.beginPath();ctx.arc(0,0,7,0,TAU);ctx.fill();ctx.strokeStyle='#8a7a5a';ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(3,-5);ctx.quadraticCurveTo(7,-10,5,-12);ctx.stroke();ctx.fillStyle='#ffd27a';ctx.beginPath();ctx.arc(5,-12,1.8+Math.random(),0,TAU);ctx.fill();}
  else{/* glass flask: round body, neck, cork, liquid glow and a highlight */ctx.fillStyle='#ffffff33';ctx.beginPath();ctx.arc(0,2,f.kind==='volatile'?7.5:5.5,0,TAU);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.arc(0,3,f.kind==='volatile'?6.2:4.6,0,TAU);ctx.fill();ctx.fillStyle='#ffffffaa';ctx.fillRect(-1.6,-6,3.2,4);ctx.fillStyle='#8a5a32';ctx.fillRect(-1.8,-8,3.6,2.2);ctx.fillStyle='#ffffffcc';ctx.beginPath();ctx.arc(-1.8,.8,1.3,0,TAU);ctx.fill();}ctx.restore();}
 /* barrels: small keg with iron hoops and a teal-gold glowing band; a lit fuse sparks on top */
 for(const b of r.barrels??[]){const lit=b.fuse!=null,pop=Math.min(1,(b.age??0)/.18)*2;/* Oct 19 (user): barrels twice the size */ctx.save();ctx.globalAlpha=.35;ctx.fillStyle='#000';ctx.beginPath();ctx.ellipse(b.x,b.y,15*pop,6*pop,0,0,TAU);ctx.fill();ctx.translate(b.x,b.y-14*pop);ctx.scale(pop,pop);ctx.globalAlpha=1;ctx.fillStyle='#6a4524';ctx.beginPath();ctx.ellipse(0,0,13,16,0,0,TAU);ctx.fill();ctx.fillStyle='#3a2a18';ctx.fillRect(-13,-9,26,3);ctx.fillRect(-13,6,26,3);
  ctx.fillStyle=lit?'#ff6a3a':'#c9b25a';ctx.globalAlpha=.9;ctx.fillRect(-12,-1.5,24,3);if(lit){ctx.fillStyle='#fff2c0';ctx.beginPath();ctx.arc(0,-18,2.5+Math.random()*2,0,TAU);ctx.fill();}ctx.restore();}
 // Status reticles: Marked (gold crosshair) and Exposed (purple broken ring).
 if(targets)for(const e of targets){if(e.state!=='alive')continue;const top=e.y-(e.radius??14)*2.6-22;if(e.rMarked>0){ctx.save();ctx.translate(e.x,top);ctx.rotate(time*2);ctx.globalAlpha=.9;ctx.strokeStyle='#ffd25a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,9,0,TAU);ctx.stroke();for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);ctx.beginPath();ctx.moveTo(6,0);ctx.lineTo(14,0);ctx.stroke();}ctx.restore();}
  if(e.rExposed>0){ctx.save();ctx.translate(e.x,e.y-8);ctx.globalAlpha=.8;ctx.strokeStyle=RANGER_COLORS.ninja;ctx.lineWidth=2.5;for(let i=0;i<3;i++){const a=time*3+i*TAU/3;ctx.beginPath();ctx.ellipse(0,0,(e.radius??14)+10,((e.radius??14)+10)*.6,0,a,a+1.4);ctx.stroke();}ctx.restore();}
  if(e.rPoison){glow(ctx,e.x,e.y-20,18+e.rPoison.stacks*3,'#7dff5a',.25);}if(e.rBurn)glow(ctx,e.x,e.y-24,20,'#ff8a3d',.28);}
 for(const h of [r.hawk,...(r.hawkFollow??[])])if(h&&!(hawk3D&&hawk3D(ctx,h,{x:h.x,y:h.y,angle:h.angle??0,t:time,phase:h.ax??0,scale:h.follow?.85:1})))drawHawk(ctx,h,time);
 for(const f of r.fx){if(shader&&(f.kind==='volleyWave'||f.kind==='volleyLaunch'))continue;const t=f.age/f.duration,k=ease(t),a=1-t,col=f.color??'#e9f6ff';
  if(f.kind==='explode'){glow(ctx,f.x,f.y-10,f.radius*(.4+.8*k),col==='#e9f6ff'?'#ff9a3d':col,.6*a);glow(ctx,f.x,f.y-14,f.radius*.35*(1-t),'#fff',.7*a);ring(ctx,f.x,f.y,f.radius*k,col==='#e9f6ff'?'#ffb45a':col,4*a+1,a);}
  else if(f.kind==='poisonBurst'){ring(ctx,f.x,f.y,f.radius*k,col==='#e9f6ff'?'#7dff5a':col,3*a+1,a);glow(ctx,f.x,f.y-12,f.radius*.8,col==='#e9f6ff'?'#7dff5a':col,.4*a);}
  else if(f.kind==='shatter'){ctx.strokeStyle='#cffaff';ctx.lineWidth=2;ctx.globalAlpha=a;for(let i=0;i<8;i++){const g=i*TAU/8;ctx.beginPath();ctx.moveTo(f.x,f.y-10);ctx.lineTo(f.x+Math.cos(g)*f.radius*k,f.y-10+Math.sin(g)*f.radius*k*.65);ctx.stroke();}ring(ctx,f.x,f.y,f.radius*k,'#9ff4ff',2,a);}
  else if(f.kind==='splash'||f.kind==='reactiveRing'||f.kind==='cyclone'||f.kind==='smokePop'||f.kind==='volleyWave'){const c=f.kind==='reactiveRing'?'#9ff4ff':f.kind==='cyclone'?RANGER_COLORS.ninja:f.kind==='smokePop'?'#8b7bb0':col;ring(ctx,f.x,f.y,f.radius*(f.kind==='volleyWave'?1-.2*k:k),c,3*a+1,a);if(f.kind==='volleyWave'){ctx.strokeStyle=c;for(let i=0;i<10;i++){const g=(i*2.39)%TAU,d=f.radius*((i*.37)%1),x=f.x+Math.cos(g)*d,y=f.y+Math.sin(g)*d*.65,h=(1-k)*90;ctx.globalAlpha=a;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+8,y-h-26);ctx.lineTo(x,y-h);ctx.stroke();}}else glow(ctx,f.x,f.y-8,f.radius*.7,c,.3*a,.65);}
  else if(f.kind==='line'){ctx.lineCap='round';for(const [w,al,c] of [[f.width*1.6,.25,RANGER_COLORS.gunslinger],[f.width*.5,.8,RANGER_COLORS.gunslinger],[3,1,'#fff']]){ctx.globalAlpha=al*a;ctx.strokeStyle=c;ctx.lineWidth=w*(1-.6*t);ctx.beginPath();ctx.moveTo(f.x,f.y);ctx.lineTo(f.x2,f.y2);ctx.stroke();}}
  else if(f.kind==='focus'||f.kind==='shadowBurst'||f.kind==='grandFlash'||f.kind==='swap'||f.kind==='glass'){const c=f.kind==='focus'?RANGER_COLORS.archer:f.kind==='shadowBurst'?RANGER_COLORS.ninja:f.kind==='grandFlash'?RANGER_COLORS.alchemist:col,R=f.kind==='grandFlash'?600:f.kind==='swap'?50:120;ring(ctx,f.x,f.y,R*k,c,4*a+1,a);glow(ctx,f.x,f.y-30,R*.5*(1-t*.5),c,.35*a);}
  else if(f.kind==='slash'){ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.angle);ctx.globalAlpha=a;ctx.strokeStyle=RANGER_COLORS.ninja;ctx.lineWidth=5*a+1;ctx.beginPath();ctx.arc(0,0,26,-.9,.9);ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,26,-.6,.6);ctx.stroke();ctx.restore();}
  else if(f.kind==='hawkCatch'){ring(ctx,f.x,f.y,30+60*k,'#ffcf7a',4*a+1,a);glow(ctx,f.x,f.y-30,50*(1-t*.5),'#fff3c4',.5*a);}
  else if(f.kind==='hawkMiss'){ctx.globalAlpha=a;ctx.fillStyle='#d9c4a0';for(let i=0;i<6;i++){const g=i*1.1+f.x;ctx.beginPath();ctx.ellipse(f.x+Math.cos(g)*24*k,f.y-10-k*20+Math.sin(g)*8,4,1.6,g,0,TAU);ctx.fill();}}
  else if(f.kind==='vanish')glow(ctx,f.x,f.y-30,40*(1+k),'#5b4a7a',.5*a);
  else if(f.kind==='step'){ctx.globalAlpha=.5*a;ctx.strokeStyle=RANGER_COLORS.gunslinger;ctx.lineWidth=10*a;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(f.x,f.y-30);ctx.lineTo(f.x+Math.cos(f.angle)*120*k,f.y-30+Math.sin(f.angle)*120*k);ctx.stroke();}
  else if(f.kind==='powerMuzzle'||f.kind==='volleyLaunch')glow(ctx,f.x,f.y-(f.kind==='volleyLaunch'?40:0),30+40*(f.power??.5),col,.7*a);}
 if(!shader)for(const v of r.particles){ctx.globalAlpha=Math.min(1,v.life/v.max*1.5);ctx.fillStyle=v.color;ctx.beginPath();ctx.arc(v.x,v.y-v.z,v.size,0,TAU);ctx.fill();}
 // Long Bow draw: a glow gathers at the bow and a ring tightens onto it.
 if(player&&r.lmbDraw){const f=Math.min(1,r.lmbDraw.t/r.lmbDraw.dur),a=r.lmbDraw.angle??0,x=player.x+Math.cos(a)*24,y=player.y-30+Math.sin(a)*18;glow(ctx,x,y,8+16*f,ARROW_COLORS[r.arrow]??'#e9f6ff',.35+.45*f);ring(ctx,x,y,30*(1-f)+6,'#e9f6ff',1.5,.3+.5*f,1);}
 if(player&&r.buffs.barrage>0){const a=r.lastAim??0;glow(ctx,player.x+Math.cos(a)*26,player.y-24+Math.sin(a)*26,22+Math.random()*10,RANGER_COLORS.gunslinger,.7);}
 rangerSoftUpper(ctx,r,player);
 ctx.restore();}

// Hunting hawk: golden glow, body and flapping wings, turned along its flight.
function drawHawk(ctx,h,time){ctx.save();glow(ctx,h.x,h.y,h.follow?22:28,'#ffcf7a',.45);ctx.translate(h.x,h.y);ctx.rotate(h.angle);const s=h.follow?.8:1,flap=Math.sin(time*28+(h.ax??0))*.8;ctx.scale(s,s);ctx.globalAlpha=1;
 ctx.fillStyle='#6b4a2a';ctx.strokeStyle='#ffe2a0';ctx.lineWidth=1.2;for(const side of [-1,1]){ctx.beginPath();ctx.moveTo(2,0);ctx.quadraticCurveTo(-4,side*(10+8*flap),-12,side*(16+10*flap));ctx.quadraticCurveTo(-6,side*6,-4,0);ctx.closePath();ctx.fill();ctx.stroke();}
 ctx.fillStyle='#8a6238';ctx.beginPath();ctx.ellipse(0,0,10,4,0,0,TAU);ctx.fill();ctx.fillStyle='#f4d27a';ctx.beginPath();ctx.moveTo(10,0);ctx.lineTo(15,-1.5);ctx.lineTo(10,2);ctx.fill();ctx.fillStyle='#5a3a1e';ctx.beginPath();ctx.moveTo(-9,0);ctx.lineTo(-16,-4);ctx.lineTo(-16,4);ctx.fill();ctx.restore();}
